<aside class="pos-v3-cart card">
    <div class="card-header d-flex justify-content-between"><span><i class="fas fa-shopping-cart mr-2"></i>ตะกร้าสินค้า</span><button id="v3-new-bill" type="button" class="btn btn-sm btn-light">บิลใหม่</button></div>
    <div id="v3-cart-items" class="pos-v3-cart-items"><div class="pos-v3-empty">ยังไม่มีสินค้า<br><small>คลิกสินค้า หรือยิง Barcode เพื่อเริ่มขาย</small></div></div>
    <div class="pos-v3-cart-footer">
        <div class="d-flex justify-content-between"><span>ยอดสินค้า</span><strong id="v3-subtotal">0.00</strong></div>
        <div class="d-flex justify-content-between"><span>ค่าจัดส่ง</span><strong id="v3-delivery-fee">0.00</strong></div>
        <div class="d-flex justify-content-between align-items-center"><label for="v3-discount">ส่วนลด</label><input id="v3-discount" class="form-control form-control-sm w-50 text-right" value="0.00" inputmode="decimal"></div>
        <div class="d-flex justify-content-between align-items-center mt-3 pos-v3-total"><span>ยอดสุทธิ</span><strong id="v3-total">0.00</strong></div>
        <button id="v3-note-button" type="button" class="btn btn-outline-secondary btn-block mt-2"><i class="fas fa-sticky-note mr-1"></i>หมายเหตุ</button>
        <button id="v3-submit" type="button" class="btn btn-success btn-lg btn-block mt-2"><i class="fas fa-check mr-1"></i>รับเงิน / บันทึก (F9)</button>
    </div>
